See https://github.com/LLK/scratch-paint/issues/13 */

$ui-pane-border: #D9D9D9;
$ui-pane-gray: #F9F9F9;
$ui-background-blue: #e8edf1;

$text-primary: #575e75;

$looks-secondary: #855CD6;
$looks-transparent: hsla(260, 60%, 60%, 0.35); /* 35% transparent version of looks-secondary */

$red-primary: #FF661A;
$red-tertiary: #E64D00;

$sound-primary: #CF63CF;
$sound-tertiary: #A63FA6;

$control-primary: #FFAB19;

$data-primary: #FF8C1A;

$form-border: #E9EEF2;
/* DO NOT EDIT
@todo This file is copied from GUI and should be pulled out into a shared library.
See https://github.com/LLK/scratch-paint/issues/13 */

/* ACTUALLY, THIS IS EDITED ;)
THIS WAS CHANGED ON 10/25/2017 BY @mewtaylor TO ADD A VARIABLE FOR THE SMALLEST
GRID UNITS.

ALSO EDITED ON 11/13/2017 TO ADD IN CONTANTS FOR LAYOUT FROM `layout-contents.js`*/

$space: 0.5rem;
$grid-unit: .25rem;

$sprites-per-row: 5;

$menu-bar-height: 3rem;
$sprite-info-height: 6rem;
$stage-menu-height: 2.75rem;

$library-header-height: 4.375rem;

$form-radius: calc($space / 2);

/* layout contants from `layout-constants.js`, minus 1px */
$full-size: 1095px;
$full-size-paint: 1256px;
@import "../../css/colors.css";
@import "../../css/units.css";

.mode-tools {
    display: flex;
    min-height: 3rem;
    align-items: center;
}

.mode-tools-icon {
    margin-right: calc(2 * $grid-unit);
    width: 2rem;
    height: 2rem;
}

[dir="ltr"] .mod-dashed-border {
    border-right: 1px dashed $ui-pane-border;
    padding-right: calc(3 * $grid-unit);
}

[dir="rtl"] .mod-dashed-border {
    border-left: 1px dashed $ui-pane-border;
    padding-left: calc(3 * $grid-unit);
}

.mod-labeled-icon-height {
    display: flex;
    height: 2.85rem; /* for the second row so the dashed borders are equal in size */
    align-items: center;
}
